contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(c).balance >= v || address(this).balance >= v);
        uint cBefore = address(c).balance;
        uint meBefore = address(this).balance;
        bool reverted;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(
            reverted ||
            (address(c).balance == cBefore - v && address(this).balance == meBefore + v)
        );
    }
}

